# ---------------------------------------------------------
# MAIN VIRUS LIST ENDPOINT (UPDATED WITH NEW HEADERS)
# ---------------------------------------------------------
@router.get("/list")
def get_virus_list(
    from_id: int,
    to_id: int,
    token: str,
    _ = Depends(require_multi_token),
    db: Session = Depends(get_db)
):
    if from_id < 1 or to_id < from_id:
        raise HTTPException(status_code=400, detail="Invalid ID range")

    viruses = []

    for vid in range(from_id, to_id + 1):
        if vid in VIRUS_DB:
            v = VIRUS_DB[vid]

            viruses.append({
                "virus_id": vid,
                "name": v["name"],
                "mass_fg": v["mass_fg"],
                "antigen": v["antigen"],
                "antibody": v["antibody"],
                "transmission": v.get("transmission", v.get("transmission_mode")),

                # ⭐ NEW FIELDS FOR SECOND TABLE
                "temperature_c": v["temperature_c"],
                "humidity": v["humidity"],
                "flow_rate": v["flow_rate"],
                "deposition_rate_s": v["deposition_rate_s"],
                "time_to_detection_s": v["time_to_detection_s"]
            })

    return {"viruses": viruses}
